create or replace function public.generate_order_installment_schedule(_order_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare o public.orders; n integer; base numeric; remainder numeric; i integer; due date; begin select * into o from public.orders where id=_order_id for update; if not found then raise exception 'Order not found'; end if; if lower(coalesce(o.plan_type,'')) in ('outright','full','cash') or coalesce(o.months,0)<=0 then return 0; end if; if exists(select 1 from public.order_installments where order_id=_order_id) then return (select count(*)::int from public.order_installments where order_id=_order_id); end if; n:=o.months; base:=round(coalesce(o.total_amount,0)/n,2); remainder:=coalesce(o.total_amount,0)-(base*(n-1)); for i in 1..n loop due:=current_date + ((i-1)*30); insert into public.order_installments(order_id,installment_number,due_date,amount_due,amount_paid,balance,status) values(_order_id,i,due,case when i=n then remainder else base end,0,case when i=n then remainder else base end,'pending'); end loop; return n; end; $$; revoke all on function public.generate_order_installment_schedule(uuid) from public; grant execute on function public.generate_order_installment_schedule(uuid) to authenticated;
